    (function () {
        const cards = document.querySelectorAll('.mm-chk-empty');
        cards.forEach(card => {
            const checkStr = card.getAttribute('data-check').trim();
            if (
                !checkStr ||
                checkStr === '无' ||
                checkStr === 'null' ||
                checkStr.includes('}}')
            ) {
                card.style.display = 'none';
                card.classList.remove('mm-chk-empty');
            }
        });

        const emojiBoxes = document.querySelectorAll('.mm-dish-emoji');
        emojiBoxes.forEach(box => {
            const content = box.textContent.trim();
            if (!content) return;

            const isHttp = /^https?:\/\//i.test(content);
            const isPng = /\.png$/i.test(content);

            if (isHttp) {
                let imgStyle = '';
                if (!isPng) {
                    imgStyle = `
                        border-radius: 12px;
                        border: 3px solid var(--mm-sticker-outline);
                        background: #fff;
                    `;
                }

                box.innerHTML = `
                    <img
                        src="${content}"
                        alt="dish image"
                        style="
                            width: 100%;
                            max-width: 90px;
                            height: auto;
                            object-fit: contain;
                            filter: drop-shadow(0px 8px 6px rgba(0,0,0,0.25));
                            ${imgStyle}
                        "
                    >
                `;
            } else {
                box.textContent = content;
            }
        });

        const observer = new IntersectionObserver(
            (entries) => {
                entries.forEach((entry, index) => {
                    if (entry.isIntersecting) {
                        setTimeout(() => {
                            entry.target.classList.add('is-visible');
                        }, index * 120);
                        observer.unobserve(entry.target);
                    }
                });
            },
            { threshold: 0.05 }
        );

        const validCards = document.querySelectorAll('.mm-chk-empty');
        validCards.forEach(el => observer.observe(el));

        const wrapper = document.getElementById('mm-wrapper');
        const sparkSymbols = ['✦', '✧', '⋆', '·'];
        const count = 6;

        for (let i = 0; i < count; i++) {
            const spark = document.createElement('div');
            const symbol = sparkSymbols[Math.floor(Math.random() * sparkSymbols.length)];
            const size = Math.random() * 8 + 8;
            const duration = Math.random() * 4 + 4;
            const delay = Math.random() * 3;

            spark.innerHTML = symbol;
            spark.style.cssText = `
                position: absolute;
                color: #D4AF37;
                font-size: ${size}px;
                top: ${Math.random() * 85 + 5}%;
                left: ${Math.random() * 85 + 7}%;
                z-index: 1;
                pointer-events: none;
                opacity: 1;
                text-shadow: 0 0 6px rgba(212, 175, 55, 0.7);
                animation: magicDustFloat ${duration}s ease-in-out ${delay}s infinite alternate;
            `;
            wrapper.appendChild(spark);
        }

        function fitTextToOneLine() {
            const autoFitTargets = document.querySelectorAll('.mm-main-title, .mm-dish-name-zh, .mm-dish-name-en');

            autoFitTargets.forEach(el => {
                el.style.fontSize = '';
                const parentWidth = el.parentElement ? el.parentElement.clientWidth : el.clientWidth;
                if (!parentWidth) return;

                const currentScrollWidth = el.scrollWidth;
                const currentFontSize = parseFloat(window.getComputedStyle(el).fontSize);

                if (currentScrollWidth > parentWidth) {
                    const ratio = parentWidth / currentScrollWidth;
                    const newSize = Math.floor(currentFontSize * ratio * 0.98);
                    el.style.fontSize = `${newSize}px`;
                }
            });
        }

        fitTextToOneLine();
        window.addEventListener('resize', fitTextToOneLine);
        if (document.fonts && document.fonts.ready) {
            document.fonts.ready.then(fitTextToOneLine);
        }
    })();
</script>

