    /*
       不规则纸签
    */

    clip-path:
        polygon(
            0 8%,
            100% 0,
            95% 100%,
            80% 87%,
            68% 100%,
            53% 87%,
            38% 100%,
            26% 87%,
            7% 100%
        );

