<script>

(function() {


    /* =====================================================
       标题描边同步
    ===================================================== */

    function updateAchievementCardLayout() {

        document
            .querySelectorAll(
                '.pop-sticker-card'
            )
            .forEach(card => {

                const title =
                    card.querySelector(
                        '.sticker-title'
                    );

                if (!title) return;

                title.setAttribute(
                    'data-title',
                    title.textContent || ''
                );

            });

    }


    updateAchievementCardLayout();


    requestAnimationFrame(
        updateAchievementCardLayout
    );


    window.addEventListener(
        'resize',
        updateAchievementCardLayout
    );


    if (
        document.fonts &&
        document.fonts.ready
    ) {

        document.fonts.ready
            .then(
                updateAchievementCardLayout
            )
            .catch(
                () => {}
            );

    }


    /* =====================================================
       滚动渐显
    ===================================================== */

    const observer =
        new IntersectionObserver(

            (entries) => {

                entries.forEach(entry => {

                    if (
                        entry.isIntersecting
                    ) {

                        entry.target
                            .classList
                            .add('visible');

                        observer.unobserve(
                            entry.target
                        );

                    }

                });

            },

            {
                threshold:
                    0.1
            }

        );


    document
        .querySelectorAll(
            '.reveal-section'
        )
        .forEach(el => {

            observer.observe(el);

        });

})();

</script>

