<script>
(function(){
    // 找出所有尚未渲染的报纸实例
    const instances = document.querySelectorAll('.chef-paper-instance:not(.rendered)');

    instances.forEach(instance => {
        instance.classList.add('rendered');

        // 1. 获取 AI 生成的原始纯文本，主动剔除可能遗留的思维链标签
        let rawData = instance.querySelector('.paper-data').textContent || '';
        rawData = rawData.replace(/^[\s\S]*<\/(?:think|thinking)>/i, '');

        // 2. 利用正则精准捕获由【标签名】包裹的键值对内容，兼容折行和省略
        const dataMap = {};
        const regex = /【(.*?)】\s*([\s\S]*?)(?=【|$)/g;
        let match;
        while ((match = regex.exec(rawData)) !== null) {
            dataMap[match[1].trim()] = match[2].trim();
        }

        // 3. 获取我们藏在 <template> 中的完美 HTML
        const tpl = instance.querySelector('.paper-tpl').innerHTML;

        // 4. 将模板中的 {{变量}} 进行全量无痛替换
        const finalHtml = tpl.replace(/\{\{(.*?)\}\}/g, (m, key) => {
            const val = dataMap[key.trim()];
            // 容错处理：如果 AI 没生成某个字段，则留空，不暴露占位符
            return val !== undefined ? val : '';
        });

        // 5. 渲染出图
        instance.querySelector('.paper-render').innerHTML = finalHtml;
    });
})();
</script>

</body>
</html>
