            pointer-events: none;
            z-index: 5;
        }

        /* 顶部 */
        .header {
            padding: 38px 25px 32px;
            text-align: center;
            border-bottom: 1px solid var(--wood);
            background:
                radial-gradient(circle at 50% 0%, rgba(255,255,255,.12), transparent 46%),
                linear-gradient(145deg, var(--green-light), var(--green)),
                var(--green);
            color: #fff8e9;
            position: relative;
            overflow: hidden;
        }

        .header::before,
        .header::after {
            content: "";
            position: absolute;
            top: 50%;
            width: 20%;
            height: 1px;
            background: rgba(240,223,188,.65);
        }

        .header::before {
            left: 5%;
        }

        .header::after {
            right: 5%;
        }

        .header-small {
            font-family: "Playfair Display", "Noto Serif SC", serif;
            font-size: 12px;
            letter-spacing: 4px;
            color: #e9dfc8;
            margin-bottom: 9px;
        }

        .header-title {
            font-family: "Noto Serif SC", serif;
            font-size: clamp(28px, 5vw, 44px);
            letter-spacing: 8px;
            margin: 0;
            font-weight: 900;
            color: #fff9ec;
            text-shadow: 0 1px 1px rgba(48,70,51,.3);
        }

        .header-sub {
            margin-top: 12px;
            font-family: "Playfair Display", "Noto Serif SC", serif;
            font-size: 13px;
            color: #e9dfcb;
            letter-spacing: 2px;
        }

        /* 通用区域 */
        .section {
            padding: 31px clamp(18px, 5vw, 48px);
            border-bottom: 1px dashed var(--inset);
            background: rgba(251,246,236,.72);
            position: relative;
        }

        .section:last-child {
            border-bottom: 0;
        }

        .section-title {
            text-align: center;
            font-size: 20px;
            letter-spacing: 4px;
            margin: 0 0 9px;
            color: var(--wood);
            position: relative;
        }

        .section-title::before,
        .section-title::after {
            content: "";
            display: inline-block;
            vertical-align: middle;
            width: 34px;
            height: 1px;
            background: var(--tab-accent);
            margin: 0 12px;
        }

        .section-desc {
            text-align: center;
            color: var(--muted);
            font-size: 12px;
            margin-bottom: 23px;
        }

        /* =========================================================
           地图
           ========================================================= */
        .map-wrap {
            background:
                linear-gradient(rgba(255,255,255,.35), rgba(255,255,255,.35)),
                var(--paper-deep);
            border: 1px solid var(--line);
            border-radius: var(--radius-lg);
            padding: 13px;
            box-shadow:
                inset 0 0 0 1px rgba(255,255,255,.6),
                0 4px 12px rgba(74,56,44,.05);
            position: relative;
        }

        .map-wrap::before {
            content: "✦";
            position: absolute;
            top: 10px;
            left: 15px;
            color: rgba(137,100,71,.4);
            font-size: 11px;
            pointer-events: none;
        }

        .map-wrap::after {
            content: "✦";
            position: absolute;
            right: 15px;
            bottom: 10px;
            color: rgba(137,100,71,.4);
            font-size: 11px;
            pointer-events: none;
        }

        .map {
            width: 100%;
            display: block;
            border-radius: 10px;
        }

        .map-land {
            fill: #eee5d4;
            stroke: #cbbda7;
            stroke-width: 3;
        }

        .map-region {
            fill: rgba(255,255,255,.23);
            stroke: #c9bba6;
            stroke-width: 1.5;
            stroke-dasharray: 5 5;
        }

        .map-region-label {
            font-family: "Noto Serif SC", serif;
            font-size: 17px;
            fill: #786b59;
            text-anchor: middle;
            pointer-events: none;
        }

        .map-town {
            cursor: pointer;
        }

        .map-town circle:not(.map-hit-area) {
            fill: #fffaf0;
            stroke: #8d7c64;
            stroke-width: 2;
            transition: .18s ease;
        }

        .map-town .map-hit-area {
            fill: transparent;
            stroke: none;
            pointer-events: all;
            cursor: pointer;
        }

        .map-town text {
            font-family: "Noto Serif SC", serif;
            font-size: 14px;
            fill: #554b3e;
            text-anchor: middle;
            pointer-events: all;
            cursor: pointer;
        }

        @media (hover: hover) {
            .map-town:hover circle:not(.map-hit-area) {
                fill: #f0dfbc;
                stroke: var(--orange);
            }
        }

        .map-town.selected circle:not(.map-hit-area) {
            fill: var(--gold);
            stroke: #765520;
            stroke-width: 3;
        }

        .map-town.selected text {
            font-weight: bold;
            fill: #6c4d1f;
        }

        .map-town.newbie circle:not(.map-hit-area) {
            stroke: #bd8d2f;
            stroke-width: 3;
        }

        .map-town.newbie text {
            font-weight: bold;
        }

        /* 地图下面的当前地点 */
        .selected-location {
            margin-top: 15px;
            padding: 13px 16px;
            border: 1px solid var(--line);
            border-radius: var(--radius-md);
            background: var(--tab-active);
            text-align: center;
            font-size: 14px;
            color: var(--ink);
            box-shadow:
                inset 0 0 0 1px rgba(255,255,255,.45),
                0 3px 8px rgba(74,56,44,.035);
        }

        .selected-location strong {
            color: var(--orange);
            font-weight: 700;
        }

        .newbie-label {
            display: inline-block;
            margin-left: 7px;
            padding: 3px 8px;
            border: 1px solid #c39a4e;
            border-radius: 20px;
            color: #9a722d;
            background: rgba(255,248,224,.65);
            font-size: 10px;
            letter-spacing: 1px;
        }

        /* =========================================================
           区域说明
           ========================================================= */
        .region-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 12px;
        }

        .region-card {
            padding: 15px;
            border: 1px solid var(--line);
            border-radius: var(--radius-md);
            background: var(--paper-deep);
            box-shadow:
                0 3px 9px rgba(74,56,44,.045),
                inset 0 0 0 1px rgba(255,255,255,.48);
            transition: .2s ease;
            position: relative;
            overflow: hidden;
        }

        .region-card::before {
            content: "";
            position: absolute;
            left: 0;
            top: 0;
            bottom: 0;
            width: 4px;
            background: var(--green);
            opacity: .7;
        }

        .region-card:hover {
            background: #faefe0;
            border-color: var(--gold-dark);
            transform: translateY(-2px);
            box-shadow: 0 6px 14px rgba(74,56,44,.08);
        }

        .region-name {
            font-size: 14px;
            font-weight: bold;
            margin-bottom: 6px;
            color: var(--wood);
            padding-left: 5px;
        }

        .region-center {
            font-size: 11px;
            color: var(--orange);
            margin-bottom: 8px;
            padding-left: 5px;
        }

        .region-towns {
            font-size: 11px;
            color: var(--muted);
            line-height: 1.8;
            padding-left: 5px;
        }

        /* =========================================================
           表单
           ========================================================= */
        .form-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 19px 22px;
        }

        .form-group {
            display: flex;
            flex-direction: column;
        }

        .form-group.full {
            grid-column: 1 / -1;
        }

        .form-label {
            font-size: 13px;
            font-weight: bold;
            margin-bottom: 7px;
            color: var(--wood);
        }

        .required::after {
            content: " *";
            color: var(--red);
        }

        input,
        select,
        textarea {
            width: 100%;
            border: 1px solid var(--line);
            border-radius: var(--radius-sm);
            background: rgba(255,255,255,.72);
            color: var(--ink);
            padding: 11px 13px;
            font-family: "Noto Serif SC", serif;
            font-size: 14px;
            outline: none;
            transition: .18s ease;
            box-shadow:
                inset 0 1px 2px rgba(74,56,44,.035),
                0 1px 1px rgba(255,255,255,.5);
        }

        input::placeholder,
        textarea::placeholder {
            color: #a09280;
        }

        input:hover,
        select:hover,
        textarea:hover {
            border-color: #c2a272;
            background: #fffaf0;
        }

        input:focus,
        select:focus,
        textarea:focus {
            border-color: var(--gold-dark);
            background: #fffdf8;
            box-shadow:
                0 0 0 3px rgba(194,147,57,.1),
                inset 0 1px 2px rgba(74,56,44,.025);
        }

        textarea {
            min-height: 105px;
            resize: vertical;
            line-height: 1.75;
        }

        /* =========================================================
           主线选择
           ========================================================= */
        .story-list {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 13px;
        }

        .story-option {
            position: relative;
        }

        .story-option input {
            position: absolute;
            opacity: 0;
            pointer-events: none;
        }

        .story-card {
            display: block;
            height: 100%;
            padding: 18px;
            border: 1px solid var(--line);
            border-radius: var(--radius-md);
            background: var(--paper-deep);
            cursor: pointer;
            transition: .2s ease;
            box-shadow:
                0 3px 9px rgba(74,56,44,.04),
                inset 0 0 0 1px rgba(255,255,255,.45);
            position: relative;
            overflow: hidden;
        }

        .story-card::before {
            content: "";
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            height: 3px;
            background: var(--tab-accent);
            opacity: .58;
            transform: scaleX(.3);
            transform-origin: left;
            transition: .2s ease;
        }

        .story-card:hover {
            border-color: var(--gold-dark);
            background: #faefe0;
            transform: translateY(-2px);
            box-shadow: 0 7px 14px rgba(74,56,44,.075);
        }

        .story-card:hover::before {
            transform: scaleX(1);
        }

        .story-option input:checked + .story-card {
            border-color: var(--gold-dark);
            background:
                linear-gradient(rgba(240,223,188,.46), rgba(240,223,188,.46)),
                #f6e8c8;
            box-shadow:
                inset 0 0 0 1px rgba(137,100,71,.2),
                0 5px 13px rgba(74,56,44,.07);
        }

        .story-option input:checked + .story-card::before {
            background: var(--green);
            transform: scaleX(1);
            opacity: .9;
        }

        .story-name {
            font-weight: bold;
            font-size: 15px;
            margin-bottom: 8px;
            color: var(--wood);
        }

        .story-text {
            font-size: 12px;
            line-height: 1.8;
            color: var(--muted);
        }

        /* 主线可编辑 */
        .story-editor {
            margin-top: 16px;
            display: none;
            padding: 14px;
            background: rgba(246,238,221,.72);
            border: 1px solid var(--line);
            border-radius: var(--radius-md);
        }

        .story-editor.show {
            display: block;
        }

        .story-editor-label {
            font-size: 12px;
            color: var(--muted);
            margin-bottom: 8px;
        }

        /* 厨师目标 */
        .goal-list {
            display: flex;
            flex-wrap: wrap;
            gap: 9px;
        }

        .goal-option {
            position: relative;
        }

        .goal-option input {
            position: absolute;
            opacity: 0;
            pointer-events: none;
        }

        .goal-label {
            display: block;
            padding: 9px 16px;
            border: 1px solid var(--line);
            border-radius: 20px;
            background: var(--paper-deep);
            cursor: pointer;
            font-size: 12px;
            transition: .2s;
            color: var(--ink);
            box-shadow: inset 0 0 0 1px rgba(255,255,255,.35);
        }

        .goal-label:hover {
            background: #faefe0;
            border-color: var(--gold-dark);
            transform: translateY(-1px);
        }

        .goal-option input:checked + .goal-label {
            border-color: var(--gold-dark);
            background: var(--tab-active);
            color: #61462f;
            box-shadow:
                inset 0 0 0 1px rgba(137,100,71,.15),
                0 2px 7px rgba(74,56,44,.06);
        }

        /* =========================================================
           提交
           ========================================================= */
        .submit-area {
            text-align: center;
            padding-top: 10px;
            margin-top: 32px;
            position: relative;
        }

        .submit-area::before {
            content: "";
            display: block;
            width: 120px;
            height: 1px;
            margin: 0 auto 19px;
            background: linear-gradient(90deg, transparent, var(--line), transparent);
        }

        .submit-button {
            border: 1px solid var(--green-deep);
            border-radius: 9px;
            background:
                linear-gradient(rgba(255,255,255,.06), rgba(255,255,255,0)),
                var(--green);
            color: #fffaf0;
            padding: 13px 58px;
            font-family: "Noto Serif SC", serif;
            font-size: 15px;
            letter-spacing: 3px;
            cursor: pointer;
            transition: .2s;
            box-shadow:
                0 5px 12px rgba(74,56,44,.12),
                inset 0 1px 0 rgba(255,255,255,.12);
        }

        .submit-button:hover {
            background: var(--green-light);
            transform: translateY(-2px);
            box-shadow:
                0 7px 15px rgba(74,56,44,.16),
                inset 0 1px 0 rgba(255,255,255,.14);
        }

        .submit-button:active {
            transform: translateY(1px);
        }

        .submit-button:disabled {
            opacity: .72;
            cursor: default;
            transform: none;
        }

        /* =========================================================
           提交后的注册证
           ========================================================= */
        .certificate {
            display: none;
            margin-top: 30px;
            padding: 31px;
            border: 1px solid var(--wood);
            border-radius: var(--radius-lg);
            background:
                radial-gradient(circle at 20% 20%, rgba(190,160,100,.09), transparent 25%),
                radial-gradient(circle at 80% 70%, rgba(190,160,100,.08), transparent 25%),
                #faf4e8;
            position: relative;
            box-shadow:
                inset 0 0 0 5px rgba(194,162,114,.08),
                inset 0 0 0 6px rgba(255,255,255,.55),
                0 7px 18px rgba(74,56,44,.07);
        }

        .certificate::before {
            content: "✦";
            position: absolute;
            top: 13px;
            left: 17px;
            color: var(--gold);
            font-size: 14px;
        }

        .certificate::after {
            content: "✦";
            position: absolute;
            right: 17px;
            bottom: 13px;
            color: var(--gold);
            font-size: 14px;
        }

        .certificate.show {
            display: block;
        }

        .certificate-title {
            text-align: center;
            font-size: 22px;
            letter-spacing: 5px;
            margin-bottom: 5px;
            color: var(--wood);
            font-weight: 700;
        }

        .certificate-sub {
            text-align: center;
            font-family: "Playfair Display", serif;
            font-size: 11px;
            color: var(--muted);
            letter-spacing: 2px;
            margin-bottom: 24px;
        }

        .certificate-body {
            display: grid;
            grid-template-columns: 1fr 190px;
            gap: 25px;
            align-items: center;
        }

        .certificate-info {
            font-size: 13px;
            line-height: 2;
        }

        .certificate-info .row {
            border-bottom: 1px dotted var(--inset);
            padding: 4px 0;
        }

        .certificate-info .key {
            color: var(--muted);
            display: inline-block;
            width: 75px;
        }

        .stamp-box {
            text-align: center;
            padding: 8px;
            border-radius: 12px;
            background: rgba(255,255,255,.28);
        }

        .stamp-box img {
            width: 155px;
            height: 155px;
            object-fit: contain;
            filter: saturate(.85);
            transform: rotate(-5deg);
        }

        .stamp-name {
            font-size: 11px;
            color: var(--muted);
            margin-top: 2px;
        }

        .certificate-note {
            margin-top: 20px;
            padding-top: 16px;
            border-top: 1px solid var(--line);
            text-align: center;
            color: #7d6c53;
            font-size: 12px;
            line-height: 1.8;
        }

        /* Toast */
        .toast {
            position: fixed;
            left: 50%;
            bottom: 25px;
            transform: translate(-50%, 20px);
            background: rgba(74,56,44,.96);
            color: #fff;
            padding: 11px 19px;
            font-size: 12px;
            border-radius: 9px;
            opacity: 0;
            pointer-events: none;
            transition: .25s;
            z-index: 99999;
            max-width: calc(100vw - 30px);
            text-align: center;
            box-shadow: 0 6px 16px rgba(74,56,44,.18);
        }

        .toast.show {
            opacity: 1;
            transform: translate(-50%, 0);
        }

        /* 手机 */
        @media (max-width: 720px) {
            body {
                padding: 8px;
            }

            .cook-register {
                border-radius: 17px;
            }

            .cook-register::before {
                inset: 5px;
                border-radius: 12px;
            }

            .header {
                padding: 28px 15px 24px;
            }

            .header::before,
            .header::after {
                width: 12%;
            }

            .header-small {
                letter-spacing: 2px;
            }

            .header-title {
                letter-spacing: 5px;
            }

            .header-sub {
                letter-spacing: 1px;
            }

            .section {
                padding: 24px 14px;
            }

            .section-title {
                font-size: 18px;
                letter-spacing: 3px;
            }

            .section-title::before,
            .section-title::after {
                width: 18px;
                margin: 0 7px;
            }

            .region-grid {
                grid-template-columns: 1fr 1fr;
                gap: 9px;
            }

            .region-card {
                padding: 12px 11px;
            }

            .region-name {
                font-size: 13px;
            }

            .region-center,
            .region-towns {
                font-size: 10px;
            }

            .form-grid {
                grid-template-columns: 1fr;
                gap: 14px;
            }

            .form-group.full {
                grid-column: auto;
            }

            .story-list {
                grid-template-columns: 1fr;
            }

            .story-card {
                padding: 16px;
            }

            .certificate {
                padding: 22px 15px;
                border-radius: 14px;
            }

            .certificate-body {
                grid-template-columns: 1fr;
            }

            .stamp-box {
                order: -1;
            }

            .stamp-box img {
                width: 125px;
                height: 125px;
            }

            .submit-button {
                width: 100%;
            }
        }
    </style>
</head>
<body>
    <div class="cook-register">
        <!-- ==================== 标题 ==================== -->
        <header class="header">
            <div class="header-small">大陆美食盟会 · 厨师公会</div>
            <h1 class="header-title">初级厨师注册表</h1>
            <div class="header-sub">登记身份 · 选择出身 · 踏上厨师之路</div>
        </header>

        <!-- ==================== 出生地地图 ==================== -->
        <section class="section">
            <h2 class="section-title">◇ 出生地登记 ◇</h2>
            <div class="section-desc">
                点击地图上的城镇选择出生地
            </div>
            <div class="map-wrap">
                <!--
                    这是示意地图。
                    地理位置只用于选择出生地，不改变世界观中的实际路线。
                -->
                <svg class="map" viewBox="0 0 1000 620">
                    <!-- 大陆轮廓 -->
                    <path class="map-land"
                        d="M90 105
                           Q180 45 310 70
                           Q420 30 520 80
                           Q650 35 790 80
                           Q920 120 900 240
                           Q950 350 875 440
                           Q900 535 760 555
                           Q610 590 490 545
                           Q350 585 245 535
                           Q105 550 90 445
                           Q45 330 105 245
                           Q50 175 90 105 Z"/>
                    <!-- 六个区域的示意范围 -->
                    <path class="map-region"
                        d="M115 100 Q250 55 390 105 L365 220 Q230 205 115 245 Z"/>
                    <path class="map-region"
                        d="M350 220 Q520 180 690 225 L670 405 Q510 440 350 380 Z"/>
                    <path class="map-region"
                        d="M90 245 Q190 215 350 255 L350 410 Q200 445 100 405 Z"/>
                    <path class="map-region"
                        d="M350 400 Q510 390 670 410 L760 535 Q560 570 405 525 Z"/>
                    <path class="map-region"
                        d="M650 205 Q790 160 900 235 L875 430 Q760 445 660 390 Z"/>
                    <path class="map-region"
                        d="M390 70 Q550 45 710 95 L680 220 Q520 190 390 220 Z"/>

                    <!-- 区域名称 -->
                    <text class="map-region-label" x="245" y="100">
                        北境林带
                    </text>
                    <text class="map-region-label" x="510" y="245">
                        中央大平原
                    </text>
                    <text class="map-region-label" x="205" y="300">
                        西海岸与群岛
                    </text>
                    <text class="map-region-label" x="520" y="505">
                        南方沙漠与绿洲
                    </text>
                    <text class="map-region-label" x="785" y="285">
                        东部丘陵与林地
                    </text>
                    <text class="map-region-label" x="550" y="115">
                        高地与火山带
                    </text>

                    <!--
                        16个城镇
                        点击后会自动选择出生地。
                    -->
                    <g class="map-town" data-town="灰石镇">
                        <circle class="map-hit-area" cx="160" cy="145" r="25"/>
                        <circle cx="160" cy="145" r="8"/>
                        <text x="160" y="170">灰石镇</text>
                    </g>
                    <g class="map-town" data-town="霜语镇">
                        <circle class="map-hit-area" cx="255" cy="115" r="25"/>
                        <circle cx="255" cy="115" r="8"/>
                        <text x="255" y="140">霜语镇</text>
                    </g>
                    <g class="map-town" data-town="松针港">
                        <circle class="map-hit-area" cx="350" cy="155" r="25"/>
                        <circle cx="350" cy="155" r="8"/>
                        <text x="350" y="180">松针港</text>
                    </g>

                    <g class="map-town newbie" data-town="牧歌镇">
                        <circle class="map-hit-area" cx="405" cy="310" r="25"/>
                        <circle cx="405" cy="310" r="9"/>
                        <text x="405" y="337">牧歌镇</text>
                    </g>
                    <g class="map-town" data-town="麦穗城">
                        <circle class="map-hit-area" cx="535" cy="290" r="25"/>
                        <circle cx="535" cy="290" r="8"/>
                        <text x="535" y="317">麦穗城</text>
