            const form = document.getElementById("chef-form");
            const birthplace = document.getElementById("field-birthplace");
            const locationBox = document.getElementById("selected-location");
            const storyEditor = document.getElementById("story-editor");
            const storyText = document.getElementById("story-text");
            const certificate = document.getElementById("certificate");
            const toast = document.getElementById("toast");

            /* =====================================================
               Toast
               ===================================================== */
            function showToast(text, type) {
                toast.textContent = text;
                if (type === "error") {
                    toast.style.background = "rgba(130,65,60,.95)";
                } else {
                    toast.style.background = "rgba(65,55,43,.94)";
                }
                toast.classList.add("show");
                clearTimeout(window.__chefToastTimer);
                window.__chefToastTimer = setTimeout(function () {
                    toast.classList.remove("show");
                }, 2800);
            }

            /* =====================================================
               出生地同步
               ===================================================== */
            function updateBirthplace(town) {
                birthplace.value = town;
                const newbie =
                    town === "牧歌镇"
                        ? '<span class="newbie-label">默认新手村</span>'
                        : "";
                locationBox.innerHTML =
                    "当前出生地：<strong>" +
                    town +
                    "</strong>" +
                    newbie;
                document.querySelectorAll(".map-town").forEach(function (el) {
                    el.classList.toggle(
                        "selected",
                        el.dataset.town === town
                    );
                });
            }

            /* =====================================================
               地图点击
               ===================================================== */
            document.querySelectorAll(".map-town").forEach(function (town) {
                town.addEventListener("click", function () {
                    updateBirthplace(town.dataset.town);
                    showToast(
                        "已选择出生地：" + town.dataset.town
                    );
                });
            });

            /* =====================================================
               下拉框同步地图
               ===================================================== */
            birthplace.addEventListener("change", function () {
                updateBirthplace(this.value);
            });

            /* =====================================================
               主线选择
               ===================================================== */
            document.querySelectorAll('input[name="story"]').forEach(function (radio) {
                radio.addEventListener("change", function () {
                    if (!this.value) {
                        storyEditor.classList.remove("show");
                        storyText.value = "";
                        return;
                    }
                    storyEditor.classList.add("show");
                    storyText.value =
                        STORY_TEXTS[this.value] || "";
                    storyText.focus();
                });
            });

            /* =====================================================
               SillyTavern 文本转义
               ===================================================== */
            function escapeForST(str) {
                if (typeof str !== "string") {
                    return "";
                }
                return str.replace(
                    /(\\+)?([|{}])/g,
                    function (m, s, c) {
                        return (s || "") +
                               (s || "") +
                               "\\" +
                               c;
                    }
                );
            }

            /*
               世界书JSON/正文写入时，
               主要防止管道符打断Slash命令。
            */
            function escapeJsonForST(str) {
                if (typeof str !== "string") {
                    return "";
                }
                return str.replace(
                    /(\\+)?\|/g,
                    function (m, s) {
                        return (s || "") +
                               (s || "") +
                               "\\|";
                    }
                );
            }

            /* =====================================================
               玩家称呼处理
               ===================================================== */
            function convertUserText(text) {
                if (!text) {
                    return "";
                }
                /*
                   防止已经存在{{user}}时再次替换。
                */
                const token = "__USER_PLACEHOLDER__";
                return text
                    .replace(/\{\{user\}\}/gi, token)
                    .replace(/你/g, "{{user}}")
                    .replace(new RegExp(token, "g"), "{{user}}");
            }

            /* =====================================================
               收集非空资料
               ===================================================== */
            function collectProfile() {
                const profile = {};
                const name =
                    document.getElementById("field-name").value.trim();
                const gender =
                    document.getElementById("field-gender").value.trim();
                const age =
                    document.getElementById("field-age").value.trim();
                const town =
                    birthplace.value.trim();
                const appearance =
                    document.getElementById("field-appearance").value.trim();
                const background =
                    document.getElementById("field-background").value.trim();
                const race =
                    document.getElementById("field-race").value.trim();

                if (name) {
                    profile["姓名"] = name;
                }
                if (gender) {
                    profile["性别"] = gender;
                }
                if (age) {
                    profile["年龄"] = age;
                }
                if (town) {
                    profile["出生地"] = town;
                }
                if (appearance) {
                    profile["外貌"] = appearance;
                }
                if (background) {
                    profile["背景故事"] = background;
                }
                if (race) {
                    profile["种族"] = race;
                }

                /* 主线 */
                const selectedStory =
                    document.querySelector(
                        'input[name="story"]:checked'
                    );
                if (
                    selectedStory &&
                    selectedStory.value &&
                    storyText.value.trim()
                ) {
                    profile["厨师主线"] =
                        convertUserText(
                            storyText.value.trim()
                        );
                }

                /* 厨师目标 */
                const goal =
                    document.querySelector(
                        'input[name="goal"]:checked'
                    );
                if (goal && goal.value) {
                    profile["希望成为的厨师"] =
                        goal.value;
                }

                return profile;
            }

            /* =====================================================
               世界书写入
               ===================================================== */
            async function saveToWorldbook(profile) {
                if (typeof triggerSlash !== "function") {
                    throw new Error(
                        "酒馆助手 triggerSlash 不可用，请确认酒馆助手已启用。"
                    );
                }

                const lines = [];
                lines.push("【厨师公会注册档案】");
                Object.keys(profile).forEach(function (key) {
                    lines.push(
                        key + "：" + profile[key]
                    );
                });
                lines.push("");

                const finalContent =
                    lines.join("\n");

                const command =
                    '/setentryfield ' +
                    'file="🍳我是厨神" ' +
                    'uid=13 ' +
                    'field=content ' +
                    escapeJsonForST(finalContent);

                await triggerSlash(command);
            }

            /* =====================================================
               向SillyTavern发送开场触发文本
               ===================================================== */
            async function sendStartMessage(town) {
                if (typeof triggerSlash !== "function") {
                    throw new Error(
                        "酒馆助手 triggerSlash 不可用。"
                    );
                }

                const message =
                    "<start>在" +
                    town +
                    "报名成为初级厨师，为了第1个小镇徽章而加油吧！</start>";

                const command =
                    "/send " +
                    escapeForST(message) +
                    " | /trigger";

                await triggerSlash(command);
            }

            /* =====================================================
               注册完成证书
               ===================================================== */
            function showCertificate(profile) {
                const town =
                    profile["出生地"];
                document.getElementById("cert-name").textContent =
                    profile["姓名"] || "";
                document.getElementById("cert-gender").textContent =
                    profile["性别"] || "";
                document.getElementById("cert-age").textContent =
                    profile["年龄"] || "";
                document.getElementById("cert-birthplace").textContent =
                    town || "";
                document.getElementById("cert-goal").textContent =
                    profile["希望成为的厨师"] || "";
                document.getElementById("cert-stamp").src =
                    STAMPS[town] || "";
                document.getElementById("cert-stamp-name").textContent =
                    town + " · 厨师公会登记印章";

                certificate.classList.add("show");
                certificate.scrollIntoView({
                    behavior: "smooth",
                    block: "center"
                });
            }

            /* =====================================================
               表单提交
               ===================================================== */
            form.addEventListener("submit", async function (event) {
                event.preventDefault();

                /*
                   先检查必填项。
                */
                if (!birthplace.value) {
                    showToast(
                        "请选择出生地。",
                        "error"
                    );
                    return;
                }

                const goal =
                    document.querySelector(
                        'input[name="goal"]:checked'
                    );
                if (!goal) {
                    showToast(
                        "请选择希望成为怎样的厨师。",
                        "error"
                    );
                    return;
                }

                const profile =
                    collectProfile();
                const town =
                    profile["出生地"];

                const button =
                    document.getElementById("submit-button");

                button.disabled = true;
                button.textContent = "正在登记……";

                try {
                    /*
                       ① 写入世界书
                    */
                    await saveToWorldbook(profile);

                    /*
                       ② 显示注册证明
                    */
                    showCertificate(profile);

                    /*
                       ③ 向酒馆发送剧情触发文本
                    */
                    await sendStartMessage(town);

                    showToast(
                        "厨师登记完成，已经开始你的厨师之旅。"
                    );

                    button.textContent =
                        "登记完成";
                } catch (error) {
                    console.error(
                        "厨师登记失败：",
                        error
                    );
                    showToast(
                        "登记失败：" +
                        (error && error.message
                            ? error.message
                            : "请检查酒馆助手。"),
                        "error"
                    );
                    button.disabled = false;
                    button.textContent =
                        "重新提交";
                }
            });

            /* =====================================================
               初始化
               ===================================================== */
            updateBirthplace("牧歌镇");
        })();
    </script>
</body>
</html>
