    let statusMusicVolume = 0.7;

    try {
        const savedVolume = parseFloat(localStorage.getItem(STATUS_MUSIC_VOLUME_KEY));
        if (!Number.isNaN(savedVolume)) {
            statusMusicVolume = Math.max(0, Math.min(1, savedVolume));
        }
    } catch (e) {}

    function createStatusMusicAudio() {
        const audio = new Audio();
        audio.preload = 'auto';
        audio.loop = true;
        audio.setAttribute('playsinline', '');
        audio.addEventListener('error', () => {
            console.warn('[gourmet] STATUS 音乐加载失败:', audio.src);
        });
        return audio;
    }

    function getStatusMusicAudio() {
        if (!statusMusicAudio) statusMusicAudio = createStatusMusicAudio();
        return statusMusicAudio;
    }

    function getStatusMusicNextAudio() {
        if (!statusMusicNextAudio) statusMusicNextAudio = createStatusMusicAudio();
        return statusMusicNextAudio;
    }

    function setStatusMusicVolume(volume) {
        volume = Math.max(0, Math.min(1, Number(volume) || 0));
        statusMusicVolume = volume;
        try { localStorage.setItem(STATUS_MUSIC_VOLUME_KEY, String(volume)); } catch (e) {}
        if (statusMusicAudio) statusMusicAudio.volume = volume;
        if (statusMusicNextAudio) statusMusicNextAudio.volume = volume;
        updateMusicSettingsUI();
    }

    function fadeAudioVolume(audio, from, to, duration, token) {
        if (!audio) return;
        const startTime = performance.now();
        audio.volume = from;
        function step(now) {
            if (token !== statusMusicFadeToken) return;
            const progress = Math.min(1, (now - startTime) / duration);
            const eased = progress * (2 - progress);
            audio.volume = from + (to - from) * eased;
            if (progress < 1) requestAnimationFrame(step);
        }
        requestAnimationFrame(step);
    }

    async function crossfadeToMusic(url) {
        if (!url || statusMusicManualPaused) return;
        const token = ++statusMusicFadeToken;
        if (statusMusicFadeTimer) clearTimeout(statusMusicFadeTimer);

        const oldAudio = statusMusicAudio;
        const newAudio = getStatusMusicNextAudio();

        newAudio.pause();
        newAudio.currentTime = 0;
        newAudio.src = url;
        newAudio.volume = 0;
        newAudio.load();

        try {
            await newAudio.play();
        } catch (e) {
            return;
        }

        fadeAudioVolume(newAudio, 0, statusMusicVolume, STATUS_MUSIC_FADE_TIME, token);

        if (oldAudio && !oldAudio.paused && oldAudio.src) {
            fadeAudioVolume(oldAudio, oldAudio.volume, 0, STATUS_MUSIC_FADE_TIME, token);
            statusMusicFadeTimer = setTimeout(() => {
                if (token !== statusMusicFadeToken) return;
                oldAudio.pause();
                oldAudio.currentTime = 0;
                oldAudio.removeAttribute('src');
                oldAudio.load();
                statusMusicAudio = newAudio;
                statusMusicNextAudio = oldAudio;
                statusMusicAudio.volume = statusMusicVolume;
            }, STATUS_MUSIC_FADE_TIME + 60);
        } else {
            statusMusicAudio = newAudio;
            statusMusicNextAudio = oldAudio || null;
            statusMusicAudio.volume = statusMusicVolume;
        }
    }

    function toggleStatusMusicPlayback() {
        const audio = getStatusMusicAudio();
        if (!statusMusicUrl) return;

        if (statusMusicManualPaused) {
            statusMusicManualPaused = false;
            audio.volume = statusMusicVolume;
            audio.play().catch(() => {});
        } else {
            statusMusicManualPaused = true;
            statusMusicFadeToken++;
            audio.pause();
            if (statusMusicNextAudio) statusMusicNextAudio.pause();
        }
        updateMusicSettingsUI();
    }

    function updateMusicSettingsUI(target) {
        const $name = $('#gourmet-current-music');
        const $location = $('#gourmet-current-music-location');
        const $button = $('#gourmet-music-play-toggle');
        const $volume = $('#gourmet-music-volume');
        const $volumeText = $('#gourmet-music-volume-text');
        if (!$name.length) return;

        if (target) {
            const name = target.matchedKey === 'default' ? '环境音乐' : target.matchedKey + '主题音乐';
            $name.text(name);
            $location.text('当前地点：' + target.location);
        } else if (statusMusicUrl) {
            $location.text('音乐播放中');
        } else {
            $name.text('暂无音乐');
            $location.text('当前没有检测到 STATUS');
        }

        if ($volume.length) $volume.val(Math.round(statusMusicVolume * 100));
        if ($volumeText.length) $volumeText.text(Math.round(statusMusicVolume * 100) + '%');
        if ($button.length) {
            $button.text(statusMusicManualPaused ? '▶ 播放音乐' : 'Ⅱ 暂停音乐');
            $button.attr('title', statusMusicManualPaused ? '继续播放' : '暂停播放');
        }
    }

    function findLatestStatusMusic(allMessages) {
        if (!Array.isArray(allMessages) || allMessages.length === 0) return null;

        // 与成就扫描保持一致：不要使用 text.match() 在一条消息里遇到第一个 STATUS 就停止。
        // 从最新楼层向前找，并在当前楼层取最后一个 STATUS；因此同一楼层存在多个 STATUS 时，
        // 最下面的 STATUS 才会作为当前生效状态。
        for (let i = allMessages.length - 1; i >= 0; i--) {
            const msg = allMessages[i];
            const text = String(msg?.message || msg?.mes || '');
            if (!text) continue;

            CONFIG.statusMusicRegex.lastIndex = 0;
            const matches = Array.from(text.matchAll(CONFIG.statusMusicRegex));
            if (matches.length === 0) continue;

            const match = matches[matches.length - 1];
            const location = String(match[3] || '').trim();
            let musicUrl = CONFIG.statusMusicDefault;
            let matchedKey = 'default';

            for (const key of Object.keys(CONFIG.statusMusicRules)) {
                if (location.includes(key)) {
                    musicUrl = CONFIG.statusMusicRules[key];
                    matchedKey = key;
                    break;
                }
            }

            return {
                messageId: msg.message_id,
                location,
                musicUrl,
                matchedKey
            };
        }

        return null;
    }

    async function updateStatusMusic(allMessages, force) {
        const target = findLatestStatusMusic(allMessages);
        const audio = getStatusMusicAudio();

        // 当前聊天里没有 STATUS：停止播放器。
        if (!target) {
            if (!audio.paused) audio.pause();
            statusMusicUrl = '';
            statusMusicMessageId = null;
            statusMusicInitialized = true;
            return;
        }

        const sameTrack = statusMusicUrl === target.musicUrl;
        const sameMessage = String(statusMusicMessageId ?? '') === String(target.messageId ?? '');
        updateMusicSettingsUI(target);

        if (!force && sameTrack && sameMessage) {
            if (!statusMusicManualPaused && audio.paused) {
                try { await audio.play(); } catch (e) {}
            }
            updateMusicSettingsUI(target);
            return;
        }

        statusMusicMessageId = target.messageId;
        statusMusicUrl = target.musicUrl;
        statusMusicInitialized = true;

        if (!statusMusicManualPaused) {
            await crossfadeToMusic(target.musicUrl);
        } else {
            audio.pause();
            audio.currentTime = 0;
            audio.src = target.musicUrl;
            audio.volume = statusMusicVolume;
            audio.load();
        }
        updateMusicSettingsUI(target);
    }

    function bindStatusMusicUnlock() {
        const unlock = async () => {
            if (!statusMusicInitialized || !statusMusicUrl || statusMusicManualPaused) return;
            const audio = getStatusMusicAudio();
            if (audio.paused) {
                try { audio.volume = statusMusicVolume; await audio.play(); } catch (e) {}
            }
        };

        ['pointerdown', 'touchstart', 'click'].forEach(type => {
            document.addEventListener(type, unlock, { passive: true });
        });
    }
    let uiScale = 1.0;
    try {
        const saved = localStorage.getItem(CONFIG.scaleKey);
        if (saved) uiScale = parseFloat(saved);
    } catch(e) {}

    let currentTheme = 'default';
    try {
        const savedTheme = localStorage.getItem(CONFIG.varThemeKey);
        if (savedTheme && CONFIG.themes.some(t => t.id === savedTheme)) {
            currentTheme = savedTheme;
        } else if (savedTheme === 'true') {
            currentTheme = 'walnut';
        }
    } catch(e) {}

    const dirtyTabs = new Set(['recipe', 'badge', 'achievement']);

    function loadTwemoji() {
        if (!window.twemoji) {
            const script = document.createElement('script');
            script.src = 'https://cdn.jsdelivr.net/npm/@twemoji/api@latest/dist/twemoji.min.js';
            script.crossOrigin = 'anonymous';
            document.head.appendChild(script);
        }
    }

    function loadGoogleFonts() {
        if (!document.getElementById('gourmet-google-font')) {
            const link = document.createElement('link');
            link.id = 'gourmet-google-font';
            link.href = 'https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@400;700&family=Playfair+Display:wght@400;700&display=swap';
            link.rel = 'stylesheet';
            document.head.appendChild(link);
        }
    }

    function parseEmoji(element) {
        if (window.twemoji && element) {
            requestAnimationFrame(() => {
                try {
                    window.twemoji.parse(element, { folder: 'svg', ext: '.svg' });
                } catch (e) {}
            });
        }
    }

    function updateUIScale(newScale) {
        if (newScale !== undefined) {
            uiScale = parseFloat(newScale.toFixed(1));
            if (uiScale < 0.5) uiScale = 0.5;
            if (uiScale > 2.0) uiScale = 2.0;
            localStorage.setItem(CONFIG.scaleKey, uiScale);
        }
        $('#gourmet-scale-text').text(Math.round(uiScale * 100) + '%');
        $(`#${CONFIG.domPanelId}`).css({
            'transform': `translateX(-50%) scale(${uiScale})`,
            'transform-origin': 'top center'
        });
    }

    function applyTheme() {
        const $panel = $('#' + CONFIG.domPanelId);
        // 移除所有主题类
        $panel.removeClass(function(index, className) {
            return (className.match(/(^|\s)theme-\S+/g) || []).join(' ');
        });
        if (currentTheme !== 'default') {
            $panel.addClass('theme-' + currentTheme);
        }
        const themeObj = CONFIG.themes.find(t => t.id === currentTheme) || CONFIG.themes[0];
        $('#gourmet-theme-toggle').text(themeObj.icon).attr('title', '切换配色 (当前: ' + themeObj.name + ')');
        try {
            localStorage.setItem(CONFIG.varThemeKey, currentTheme);
        } catch(e) {}

        // ★ 动态设置背景和边框图片（使用CSS变量）
        const $mainFrame = $('.gourmet-main-frame');
        if ($mainFrame.length) {
            $mainFrame.css({
                '--gourmet-bg-image': `url('${themeObj.bgImage}')`,
                '--gourmet-frame-image': `url('${themeObj.frameImage}')`
            });
        }
    }

    function cycleTheme() {
        const currentIndex = CONFIG.themes.findIndex(t => t.id === currentTheme);
        const nextIndex = (currentIndex + 1) % CONFIG.themes.length;
        currentTheme = CONFIG.themes[nextIndex].id;
        applyTheme();
    }

    function getVars() {
        try {
            if (typeof TavernHelper !== 'undefined') return TavernHelper.getVariables({ type: 'chat' }) || {};
        } catch (e) {}
        return {};
    }

    function normalizeBadgeName(rawName) {
        let name = String(rawName ?? '').trim();
        if (!name) return '';

        // 先去除常见的包裹符号，避免 AI 输出轻微格式差异导致漏记。
        name = name.replace(/^[\s\[【「『<]+|[\s\]】」』>]+$/g, '').trim();

        const allBadges = [
            ...CONFIG.badges.national,
            ...CONFIG.badges.regions,
            ...CONFIG.badges.towns
        ];

        for (const badge of allBadges) {
            if (name === badge.name) return badge.name;
        }

        for (const badge of allBadges) {
            const aliases = CONFIG.badgeAliases[badge.name] || [];
            if (aliases.includes(name)) return badge.name;
        }

        return name;
    }

    function getLastMessageId() {
        let allMessages;
        if (typeof getChatMessages !== 'undefined') allMessages = getChatMessages('0-{{lastMessageId}}');
        else if (typeof TavernHelper !== 'undefined') allMessages = TavernHelper.getChatMessages('0-{{lastMessageId}}');
        if (!allMessages || allMessages.length === 0) return 0;
        return allMessages[allMessages.length - 1].message_id;
    }

    function performScan(mode, forceCheckpoint) {
        if (mode === undefined) mode = 'full';
        if (forceCheckpoint === undefined) forceCheckpoint = false;
        let allMessages;
        if (typeof getChatMessages !== 'undefined') allMessages = getChatMessages('0-{{lastMessageId}}');
        else if (typeof TavernHelper !== 'undefined') allMessages = TavernHelper.getChatMessages('0-{{lastMessageId}}');
        if (!allMessages) return;

        // STATUS 音乐独立于图鉴增量扫描：始终从最新聊天楼层判断当前音乐。
        // 这样即使图鉴使用 checkpoint，也不会漏掉最新 STATUS。
        updateStatusMusic(allMessages, false);

        let scanFromIndex = 0;
        let checkpoint = getCheckpoint();
        const achievementMap = new Map();
        const recipeMap = new Map();
        const unlockedBadges = new Set();

        if (mode === 'incremental' && checkpoint && checkpoint.message_id != null) {
            scanFromIndex = allMessages.findIndex(m => Number(m.message_id) > Number(checkpoint.message_id));
            if (scanFromIndex === -1) scanFromIndex = allMessages.length;
            if (checkpoint.achievements) checkpoint.achievements.forEach(a => achievementMap.set(a.name, a));
            if (checkpoint.recipes) checkpoint.recipes.forEach(r => recipeMap.set(r.nameZh, r));
            if (checkpoint.badges) checkpoint.badges.forEach(b => {
                const normalizedBadge = normalizeBadgeName(b);
                if (normalizedBadge) unlockedBadges.add(normalizedBadge);
            });
        } else {
            mode = 'full';
            const importBase = getVars()[CONFIG.varImportBaseKey];
            if (importBase && importBase.importedAtMsgId != null) {
                achievementMap.clear();
                recipeMap.clear();
                unlockedBadges.clear();
                (importBase.achievements || []).forEach(a => achievementMap.set(a.name, a));
                (importBase.recipes || []).forEach(r => recipeMap.set(r.nameZh, r));
                (importBase.badges || []).forEach(b => {
                    const normalizedBadge = normalizeBadgeName(b);
                    if (normalizedBadge) unlockedBadges.add(normalizedBadge);
                });
                scanFromIndex = allMessages.findIndex(m => Number(m.message_id) > Number(importBase.importedAtMsgId));
                if (scanFromIndex === -1) scanFromIndex = allMessages.length;
            } else {
                scanFromIndex = 0;
            }
        }

        const messagesToScan = allMessages.slice(scanFromIndex);

        for (const msg of messagesToScan) {
            const text = msg.message || msg.mes || "";
            if (!text) continue;

            if (text.includes('<magical_menu>')) {
                const regexMenuBlock = /<magical_menu>([\s\S]*?)<\/magical_menu>/gi;
                let menuMatch;
                while ((menuMatch = regexMenuBlock.exec(text)) !== null) {
                    const block = menuMatch[1];
                    const regexDish = /\[Dish\d\|(.*?)\|(.*?)\|(.*?)\|(.*?)\|(.*?)\]/g;
                    let dishMatch;
                    while ((dishMatch = regexDish.exec(block)) !== null) {
                        const icon = dishMatch[1].trim();
                        const nameZh = dishMatch[2].trim();
                        const nameEn = dishMatch[3].trim();
                        const rank = dishMatch[4].trim();
                        const desc = dishMatch[5].trim();
                        if (nameZh === '无' || icon === '无' || !nameZh) continue;
                        recipeMap.set(nameZh, { icon, nameZh, nameEn, rank, desc });
                    }
                }
            }

            if (text.includes('CMD:UNLOCK_BADGE')) {
                CONFIG.regexBadgeUnlock.lastIndex = 0;
                for (const m of text.matchAll(CONFIG.regexBadgeUnlock)) {
                    if (m[1]) {
                        const normalizedBadge = normalizeBadgeName(m[1]);
                        if (normalizedBadge) unlockedBadges.add(normalizedBadge);
                    }
                }
            }

            if (text.includes('<Achievement>')) {
                CONFIG.regexAchievement.lastIndex = 0;
                for (const m of text.matchAll(CONFIG.regexAchievement)) {
                    achievementMap.set(m[2].trim(), {
                        icon: m[1].trim(),
                        name: m[2].trim(),
                        condition: m[3].trim(),
                        reward: m[4].trim(),
                        eval: m[5].trim()
                    });
                }
            }
        }

        const currentAchievements = Array.from(achievementMap.values());
        const currentRecipes = Array.from(recipeMap.values());
        const currentBadges = Array.from(unlockedBadges);

        if (typeof TavernHelper !== 'undefined') {
            TavernHelper.insertOrAssignVariables({
                [CONFIG.varAchieveKey]: currentAchievements,
                [CONFIG.varRecipeKey]: currentRecipes,
                [CONFIG.varBadgeKey]: currentBadges
            }, { type: 'chat' });
        }

        ['recipe', 'badge', 'achievement'].forEach(t => dirtyTabs.add(t));
        if (isPanelOpen) renderActiveTab();

        if (mode === 'full') {
            const latestMsg = allMessages.length > 0 ? allMessages[allMessages.length - 1] : null;
            const latestMsgId = latestMsg ? latestMsg.message_id : 0;
            const lastCpId = checkpoint ? (checkpoint.message_id || 0) : 0;
            if (forceCheckpoint || (Number(latestMsgId) - Number(lastCpId) >= CONFIG.checkpointInterval)) {
                saveCheckpoint({
                    message_id: latestMsgId,
                    achievements: currentAchievements,
                    recipes: currentRecipes,
                    badges: currentBadges
                });
                if (forceCheckpoint && window.toastr) toastr.success(`检查点已更新`, '系统');
            }
        }

        refreshRecipePrompt(currentRecipes);
        refreshBadgePrompt(currentBadges);
    }

    function refreshRecipePrompt(recipes) {
        if (recipes.length === 0) {
            if (typeof uninjectPrompts !== 'undefined') uninjectPrompts([CONFIG.recipePromptId]);
            return;
        }
        let listStr = recipes.map(r => `- ${r.nameZh} (${r.rank})`).join('\n');
        const promptContent = `<Recipe_Book>\n[已掌握食谱]\n${listStr}\n</Recipe_Book>`;
        if (typeof uninjectPrompts !== 'undefined') uninjectPrompts([CONFIG.recipePromptId]);
        if (typeof injectPrompts !== 'undefined') injectPrompts([{ id: CONFIG.recipePromptId, position: 'in_chat', depth: CONFIG.recipeDepth, role: 'system', content: promptContent, should_scan: true }]);
    }

    function refreshBadgePrompt(unlocked) {
        let tCount = 0, rCount = 0, hasNat = false;
        unlocked.forEach(n => {
            if (CONFIG.badges.towns.some(b => b.name === n)) tCount++;
            if (CONFIG.badges.regions.some(b => b.name === n)) rCount++;
            if (CONFIG.badges.national.some(b => b.name === n)) hasNat = true;
        });

        let statusStr = '';

        if (hasNat) {
            statusStr = `[赛事阶段] 已夺得全国大赛冠军徽章，完成全国大赛。`;
        } else if (rCount >= 3) {
            statusStr = `[赛事阶段] 已获得${rCount}枚区域徽章，达到3枚区域徽章，获得参加全国大赛的资格。当前可以参加全国大赛。`;
        } else if (tCount >= 6) {
            const needRegions = 3 - rCount;
            statusStr = `[赛事阶段] 已获得${tCount}枚小镇徽章，达到6枚小镇徽章，获得参加区域赛的资格。当前正在参加区域赛事并收集区域徽章（${rCount}/3）。${needRegions > 0 ? `距离全国大赛资格还需要${needRegions}枚区域徽章。` : ''}`;
        } else {
            const needTowns = 6 - tCount;
            statusStr = `[赛事阶段] 当前已获得${tCount}枚小镇徽章，需要至少获得6枚小镇徽章才能参加区域赛。${needTowns > 0 ? `还需要${needTowns}枚小镇徽章。` : ''}`;
        }

        const promptContent = `<Badge_System>
[荣誉徽章记录]
${statusStr}
[已获得徽章明细]: ${unlocked.length > 0 ? unlocked.join(', ') : '无'}
<Rule>当{{user}}赢得比赛并获得对应徽章时输出：
<Badge_System>
CMD:UNLOCK_BADGE | [徽章全名]
</Badge_System>
赛事资格逻辑：获得至少6枚小镇徽章后，{{user}}获得参加区域赛的资格；获得至少3枚区域徽章后，{{user}}获得参加全国大赛的资格；赢得全国大赛并夺冠后获得“全国大赛冠军徽章”。
，小镇赛获得例如“灰石镇徽章”，区域赛获得例如“中央大平原徽章”。</Rule>
</Badge_System>`;
        if (typeof uninjectPrompts !== 'undefined') uninjectPrompts([CONFIG.badgePromptId]);
        if (typeof injectPrompts !== 'undefined') injectPrompts([{ id: CONFIG.badgePromptId, position: 'in_chat', depth: CONFIG.badgeDepth, role: 'system', content: promptContent, should_scan: true }]);
    }

    function getCheckpoint() {
        try {
            if (typeof TavernHelper !== 'undefined') return TavernHelper.getVariables({ type: 'chat' })[CONFIG.varCheckpointKey] || null;
        } catch(e) {}
        return null;
    }

    function saveCheckpoint(snapshot) {
        try {
            if (typeof TavernHelper !== 'undefined') TavernHelper.insertOrAssignVariables({ [CONFIG.varCheckpointKey]: snapshot }, { type: 'chat' });
        } catch(e) {}
    }

    function clearCheckpoint() {
        try {
            if (typeof TavernHelper !== 'undefined') {
                TavernHelper.insertOrAssignVariables({ [CONFIG.varCheckpointKey]: null }, { type: 'chat' });
            }
        } catch(e) {
            console.error('[gourmet] clearCheckpoint failed:', e);
        }
    }

    function scheduleScan(mode) {
        if (debounceTimer) clearTimeout(debounceTimer);
        debounceTimer = setTimeout(() => performScan(mode || 'full'), CONFIG.debounceDelay);
    }

    function renderActiveTab() {
        const $panel = $('#' + CONFIG.domPanelId);
        if (!$panel.is(':visible')) return;
        if ($('#gourmet-tab-recipe').hasClass('active') && dirtyTabs.has('recipe')) {
            renderRecipes();
            dirtyTabs.delete('recipe');
        } else if ($('#gourmet-tab-badge').hasClass('active') && dirtyTabs.has('badge')) {
            renderBadges();
            dirtyTabs.delete('badge');
        } else if ($('#gourmet-tab-ach').hasClass('active') && dirtyTabs.has('achievement')) {
            renderAchievements();
            dirtyTabs.delete('achievement');
        }
    }

    function switchTab(tab) {
        ['recipe', 'badge', 'ach', 'settings'].forEach(t => {
            $('#gourmet-tab-' + t).removeClass('active');
            $('#gourmet-list-' + t).hide();
        });
        $('#gourmet-tab-' + tab).addClass('active');
        if (tab === 'recipe') {
            $('#gourmet-list-recipe').css('display', 'flex');
            if (dirtyTabs.has('recipe')) {
                renderRecipes();
                dirtyTabs.delete('recipe');
            }
        } else if (tab === 'badge') {
            $('#gourmet-list-badge').css('display', 'flex');
            if (dirtyTabs.has('badge')) {
                renderBadges();
                dirtyTabs.delete('badge');
            }
        } else if (tab === 'ach') {
            $('#gourmet-list-ach').css('display', 'flex');
            if (dirtyTabs.has('achievement')) {
                renderAchievements();
                dirtyTabs.delete('achievement');
            }
        } else if (tab === 'settings') {
            $('#gourmet-list-settings').css('display', 'flex');
            renderSettings();
        }
    }

    function renderRecipes() {
        const recipes = getVars()[CONFIG.varRecipeKey] || [];
        const $list = $('#gourmet-list-recipe');
        $list.empty();
        if (recipes.length === 0) {
            $list.html('<div style="text-align:center; color:#896447; margin-top:40px; font-weight:bold;">尚未研发出任何食谱</div>');
            return;
        }
        const itemsHtml = recipes.map(item => {
            let iconHtml = item.icon.startsWith('http') ? `<img src="${item.icon}" style="width:30px;height:30px;object-fit:cover;border-radius:6px;">` : `<div style="font-size:24px;">${item.icon}</div>`;
            return `
            <div class="achieve-item recipe-item">
                <div class="item-header">
                    <div class="emoji-wrapper">${iconHtml}</div>
