    function gourmetSaveTextFile(filename, text, mimeType) {
        mimeType = mimeType || 'application/json';
        let downloadTriggered = false;
        try {
            const a = document.createElement('a');
            if ('download' in a) {
                const blob = new Blob([text], { type: mimeType });
                const url = URL.createObjectURL(blob);
                a.href = url;
                a.download = filename;
                a.style.display = 'none';
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);
                setTimeout(() => {
                    try { URL.revokeObjectURL(url); } catch(e) {}
                }, 4000);
                downloadTriggered = true;
            }
        } catch(e) {
            console.error('[gourmet] export failed:', e);
        }
        if (!downloadTriggered) {
            const textWindow = window.open('', '_blank');
            if (textWindow) {
                textWindow.document.write(`
                <html>
                <head>
                    <meta charset="UTF-8">
                    <title>导出图鉴数据</title>
                </head>
                <body style="padding:15px;">
                    <h3>📋 图鉴数据</h3>
                    <p>当前浏览器无法直接下载，请长按下方文本并复制。</p>
                    <textarea style="width:100%; height:70vh; box-sizing:border-box; font-size:12px;">${text.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}</textarea>
                </body>
                </html>
                `);
                textWindow.document.close();
            }
        }
        return downloadTriggered;
    }

    function renderSettings() {
        const $list = $('#gourmet-list-settings');
        if ($list.children().length > 0) {
            updateMusicSettingsUI();
            return;
        }
        $list.html(`
        <div class="gourmet-settings-group">
            <div class="gourmet-settings-grouplabel">音乐</div>
            <div class="gourmet-music-card">
                <div class="gourmet-music-info">
