                </div>
            </div>
        </div>
        <div class="gourmet-settings-group">
            <div class="gourmet-settings-grouplabel">系统备份</div>
            <div id="gourmet-scan" class="gourmet-settings-row clickable"><span>🔄 重新扫描全部楼层</span></div>
            <div id="gourmet-export-btn" class="gourmet-settings-row clickable"><span>📤 导出图鉴数据</span></div>
            <div id="gourmet-import-btn" class="gourmet-settings-row clickable"><span>📥 导入图鉴数据</span></div>
        </div>`);

        $('#gourmet-music-play-toggle').on('click', toggleStatusMusicPlayback);
        $('#gourmet-music-volume').on('input', function() {
            setStatusMusicVolume(Number(this.value) / 100);
        });
        updateMusicSettingsUI();

        $('#gourmet-scan').on('click', () => {
            if (window.toastr) toastr.info('正在重新扫描全部楼层...', '系统');
            clearCheckpoint();
            performScan('full', true);
            if (window.toastr) toastr.success('全部楼层扫描完成', '系统');
        });
        $('#gourmet-export-btn').on('click', () => {
            const vars = getVars();
            const exp = { v: 4, ach: vars[CONFIG.varAchieveKey] || [], recipe: vars[CONFIG.varRecipeKey] || [], badge: vars[CONFIG.varBadgeKey] || [] };
            gourmetSaveTextFile(`Gourmet_Backup_${new Date().getTime()}.json`, JSON.stringify(exp, null, 2), 'application/json');
            if (window.toastr) toastr.success('图鉴数据已导出', '系统');
        });
        $('#gourmet-import-btn').on('click', () => {
            const input = document.createElement('input');
            input.type = 'file'; input.accept = '.json,application/json';
            input.onchange = e => {
                const file = e.target.files[0]; if (!file) return;
                const r = new FileReader();
                r.onload = ev => {
                    try {
                        const obj = JSON.parse(ev.target.result);
                        if (obj.v !== 4) { alert('数据版本不兼容，请使用最新备份'); return; }
                        if (!confirm('导入后当前图鉴数据将被覆盖，确定吗？')) return;
                        if (typeof TavernHelper !== 'undefined') {
                            TavernHelper.insertOrAssignVariables({ [CONFIG.varAchieveKey]: Array.isArray(obj.ach) ? obj.ach : [], [CONFIG.varRecipeKey]: Array.isArray(obj.recipe) ? obj.recipe : [], [CONFIG.varBadgeKey]: Array.isArray(obj.badge) ? obj.badge : [] }, { type: 'chat' });
                            const lastMsgId = getLastMessageId();
                            TavernHelper.insertOrAssignVariables({ [CONFIG.varImportBaseKey]: { importedAtMsgId: lastMsgId, achievements: Array.isArray(obj.ach) ? obj.ach : [], recipes: Array.isArray(obj.recipe) ? obj.recipe : [], badges: Array.isArray(obj.badge) ? obj.badge : [] } }, { type: 'chat' });
                            clearCheckpoint();
                        }
                        dirtyTabs.add('recipe'); dirtyTabs.add('badge'); dirtyTabs.add('achievement');
                        if (isPanelOpen) renderActiveTab();
                        if (window.toastr) toastr.success('图鉴数据导入成功', '系统');
                    } catch (err) { console.error('[gourmet] import failed:', err); alert('读取文件失败：' + err.message); }
                };
                r.readAsText(file, 'utf-8');
            };
            document.body.appendChild(input); input.click(); document.body.removeChild(input);
        });
    }

    function togglePanel() {
        const $panel = $('#' + CONFIG.domPanelId);
        if (isPanelOpen) {
