        }
    }

    function bindEvents() {
        bindStatusMusicUnlock();
        if (typeof tavern_events !== 'undefined') {
            const bindEvent = typeof eventOn === 'function' ? eventOn : (typeof eventSource !== 'undefined' ? eventSource.on.bind(eventSource) : null);
            if (bindEvent) {
                bindEvent(tavern_events.CHARACTER_MESSAGE_RENDERED, () => scheduleScan('incremental'));
                [tavern_events.MESSAGE_DELETED, tavern_events.MESSAGE_SWIPED, tavern_events.MESSAGE_UPDATED].forEach(e => bindEvent(e, () => {
                    clearCheckpoint();
                    scheduleScan('full');
                }));
                bindEvent('generation_started', () => {
                    if (getCheckpoint()) scheduleScan('incremental');
                    else performScan('full');
                });
                bindEvent(tavern_events.CHAT_CHANGED, () => {
                    statusMusicFadeToken++;
                    if (statusMusicFadeTimer) clearTimeout(statusMusicFadeTimer);
                    [statusMusicAudio, statusMusicNextAudio].forEach(audio => {
                        if (!audio) return;
                        audio.pause(); audio.currentTime = 0; audio.removeAttribute('src'); audio.load(); audio.volume = statusMusicVolume;
                    });
                    statusMusicAudio = null;
                    statusMusicNextAudio = null;
                    statusMusicUrl = '';
                    statusMusicMessageId = null;
                    statusMusicInitialized = false;
                    statusMusicManualPaused = false;
                    $('[id^="gourmet-"]').remove();
                    setTimeout(init, 100);
                });
            }
        }
        if (typeof getButtonEvent !== 'undefined' && typeof eventOn === 'function') {
            eventOn(getButtonEvent(CONFIG.toggleButtonName), () => {
                $('#' + CONFIG.domBallId).toggle();
            });
        }
    }

