    function createUI() {
        injectStyles();
        if ($('#' + CONFIG.domBallId).length > 0) return;
        const ballHtml = `<div id="${CONFIG.domBallId}" style="position:fixed;top:40%;left:10px;width:50px;height:50px;z-index:100000;cursor:pointer;display:flex;justify-content:center;align-items:center;user-select:none;touch-action:none;"><img src="${CONFIG.customIconUrl}" style="width:50px;height:50px;object-fit:contain;"></div>`;
        const panelHtml = `
        <div id="${CONFIG.domPanelId}" style="display:none;position:fixed;top:100px;left:50%;transform:translateX(-50%);width:90%;max-width:360px;height:450px;z-index:9999;flex-direction:column;">
            <div id="gourmet-main-close-btn" style="position:absolute;top:-12px;right:-12px;width:30px;height:30px;border-radius:50%;text-align:center;line-height:24px;font-weight:bold;cursor:pointer;z-index:20;">✕</div>
            <div class="gourmet-tabs-bar">
                <div id="gourmet-tab-recipe" class="gourmet-inv-tab active">食谱<span></span></div>
                <div id="gourmet-tab-badge" class="gourmet-inv-tab">徽章</div>
                <div id="gourmet-tab-ach" class="gourmet-inv-tab">成就</div>
                <div id="gourmet-tab-settings" class="gourmet-inv-tab">设置</div>
            </div>
            <div class="gourmet-main-frame">
                <div class="gourmet-panel-container">
                    <div style="flex:1;overflow-y:auto;overflow-x:hidden;padding:5px 2px;position:relative;z-index:1;">
                        <div id="gourmet-list-recipe" style="display:flex;flex-direction:column;"></div>
                        <div id="gourmet-list-badge" style="display:none;flex-direction:column;"></div>
                        <div id="gourmet-list-ach" style="display:none;flex-direction:column;"></div>
                        <div id="gourmet-list-settings" style="display:none;flex-direction:column;padding:5px 2px;"></div>
                    </div>
                    <div class="gourmet-bottom-bar">
                        <div class="gourmet-scale-container">
                            <div id="gourmet-scale-minus" style="cursor:pointer;padding:0 6px;font-size:14px;color:#896447;user-select:none;">➖</div>
                            <div id="gourmet-scale-text" style="font-size:12px;font-weight:bold;color:#4a382c;min-width:34px;text-align:center;">100%</div>
                            <div id="gourmet-scale-plus" style="cursor:pointer;padding:0 6px;font-size:14px;color:#896447;user-select:none;">➕</div>
                        </div>
                        <div id="gourmet-theme-toggle" style="cursor:pointer;font-size:18px;user-select:none;" title="切换配色">☀</div>
                    </div>
                </div>
            </div>
        </div>`;
        $('body').append(ballHtml + panelHtml);
        $('#gourmet-tab-recipe').click(() => switchTab('recipe'));
        $('#gourmet-tab-badge').click(() => switchTab('badge'));
        $('#gourmet-tab-ach').click(() => switchTab('ach'));
        $('#gourmet-tab-settings').click(() => switchTab('settings'));
        $('#gourmet-main-close-btn').click(togglePanel);
        bindBallEvents();
        $('#gourmet-scale-minus').click(() => updateUIScale(uiScale - 0.1));
        $('#gourmet-scale-plus').click(() => updateUIScale(uiScale + 0.1));
        $('#gourmet-theme-toggle').click(cycleTheme);
    }

    function bindBallEvents() {
        const $ball = $('#' + CONFIG.domBallId);
        const ballEl = $ball[0];
        let touchDragging = false;
        let mouseDragging = false, isMouseDown = false;
        let startX, startY, initL, initT;

        $ball.on('touchstart', e => {
            touchDragging = false;
            const t = e.touches[0];
            startX = t.clientX; startY = t.clientY;
            const r = ballEl.getBoundingClientRect();
            initL = r.left; initT = r.top;
        });
        $ball.on('touchmove', e => {
            const t = e.touches[0];
            const moveX = t.clientX - startX, moveY = t.clientY - startY;
            if (Math.abs(moveX) > 10 || Math.abs(moveY) > 10) {
                touchDragging = true;
                $ball.css({ left: initL + moveX + 'px', top: initT + moveY + 'px', transform: 'none' });
            }
            e.preventDefault();
        });
        $ball.on('touchend', () => {
            if (!touchDragging) togglePanel();
            touchDragging = false;
        });

        ballEl.addEventListener('pointerdown', e => {
            if (e.pointerType !== 'mouse' || e.button !== 0) return;
            isMouseDown = true;
            mouseDragging = false;
            startX = e.clientX; startY = e.clientY;
            const r = ballEl.getBoundingClientRect();
            initL = r.left; initT = r.top;
            try { ballEl.setPointerCapture(e.pointerId); } catch(err) {}
            e.preventDefault();
        });
        ballEl.addEventListener('pointermove', e => {
            if (e.pointerType !== 'mouse' || !isMouseDown) return;
            const moveX = e.clientX - startX, moveY = e.clientY - startY;
            if (!mouseDragging && (Math.abs(moveX) > 5 || Math.abs(moveY) > 5)) {
                mouseDragging = true;
                ballEl.style.cursor = 'grabbing';
            }
            if (mouseDragging) {
                ballEl.style.left = (initL + moveX) + 'px';
                ballEl.style.top = (initT + moveY) + 'px';
                ballEl.style.transform = 'none';
            }
        });
        ballEl.addEventListener('pointerup', e => {
            if (e.pointerType !== 'mouse') return;
            if (!mouseDragging) togglePanel();
            isMouseDown = false;
            mouseDragging = false;
            ballEl.style.cursor = 'pointer';
        });
        ballEl.addEventListener('pointercancel', e => {
            if (e.pointerType !== 'mouse') return;
            isMouseDown = false;
            mouseDragging = false;
        });
    }

    function init() {
        if (!window.$ || (typeof getChatMessages === 'undefined' && typeof TavernHelper === 'undefined')) {
            if (initRetryCount++ < 20) setTimeout(init, 250);
            return;
        }
        $('[id^="gourmet-"]').remove();
        loadTwemoji();
        loadGoogleFonts();
        createUI();
        bindEvents();
        performScan('full');
        updateUIScale();
        applyTheme();
    }

    function cleanup() {
        statusMusicFadeToken++;
        if (statusMusicFadeTimer) clearTimeout(statusMusicFadeTimer);
        [statusMusicAudio, statusMusicNextAudio].forEach(audio => {
            if (audio) { audio.pause(); audio.currentTime = 0; }
        });
        $('[id^="gourmet-"]').remove();
        if (debounceTimer) {
            clearTimeout(debounceTimer);
        }
    }

    $(window).on('pagehide', cleanup);
    $(document).ready(init);
})();
